import {sections,words,sources} from './content.js';
import {workbook} from './xlsx.js';
import {defaultCourses} from './course-catalog.js';
import {extensionDefinitions,sourceMapping,normalizeExtensions} from './extensions.js';
import {taskDefinitions,taskStates,freshTracking,normalizeTracking,metrics,safeTrainingURL} from './tracking-data.js';
const KEY='support-blueprint-v1';
let pageView=(typeof window!=='undefined'&&window.BLUEPRINT_SHARED)?'tracking':'questionnaire',clientPreview=false;
const unlockedCourses=new Map();
const shared=typeof window!=='undefined'&&window.BLUEPRINT_SHARED===true;
let cloud={role:'consultant',id:null,revision:0,projects:[],resources:[],access:null,events:[],members:[],ready:!shared,error:'',busy:false,dirty:false,saved:''},saveTimer=null,catalogRevision=0;
let storageOK=true;const fresh=()=>({schemaVersion:1,lang:'fr',step:0,tracking:freshTracking(),extensions:normalizeExtensions(),sections:Object.fromEntries(sections.map(s=>[s.id,{values:{},rows:[],notes:'',reviewed:false,deferred:false}]))});
let state=fresh();try{const saved=localStorage.getItem(KEY);if(saved)state=validate(JSON.parse(saved))}catch{storageOK=false}
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const t=v=>typeof v==='object'?v[state.lang]??v.en:v;const w=k=>t(words[k]||k);const tr=(fr,en)=>state.lang==='fr'?fr:en;const d=id=>state.sections[id];const section=()=>sections[state.step];let sim={};
function validate(x){if(!x||x.schemaVersion!==1||!x.sections)throw Error('schema');const n=fresh();n.lang=x.lang==='en'?'en':'fr';n.step=Number.isInteger(x.step)&&x.step>=0&&x.step<sections.length?x.step:0;for(const s of sections){const a=x.sections[s.id];if(!a||!Array.isArray(a.rows)||a.rows.length>2000)throw Error('rows');const b=n.sections[s.id];b.notes=String(a.notes||'').slice(0,20000);b.reviewed=!!a.reviewed;b.deferred=!!a.deferred;for(const f of s.fields||[])b.values[f.key]=String(a.values?.[f.key]??'').slice(0,20000);b.rows=a.rows.map(r=>Object.fromEntries((s.cols||[]).map(c=>[c.key,String(r[c.key]??'').slice(0,65536)])));}n.tracking=normalizeTracking(x.tracking);n.extensions=normalizeExtensions(x.extensions);return n;}
function persist(){if(shared){if(!cloud.ready||!cloud.id)return;cloud.dirty=true;cloud.error='';clearTimeout(saveTimer);saveTimer=setTimeout(flushCloud,750);setSaveStatus();return}try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true}catch{storageOK=false}setSaveStatus();}
function setSaveStatus(){const el=$('#savestatus');if(el)el.textContent=saveStatus()}
function saveStatus(){return shared?(cloud.error||(!cloud.ready?tr('Chargement…','Loading…'):!cloud.id?tr('Créez un projet pour enregistrer','Create a project to save'):cloud.busy||cloud.dirty?tr('Enregistrement…','Saving…'):tr('Enregistré dans le projet partagé','Saved to the shared project'))):tr('Mode local · exportez pour conserver une copie','Local mode · export to keep a copy')}

function toast(msg){$('#toast')?.remove();const e=document.createElement('div');e.id='toast';e.role='status';e.textContent=msg;document.body.append(e);setTimeout(()=>e.remove(),3500)}
function options(opts,value){return `<option value="">—</option>`+opts.map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(o==='new'?w('new_status'):w(o))}</option>`).join('')}
function input(f,value,attrs=''){const a=`${attrs} aria-label="${esc(t(f.label))}"`;return f.type==='select'?`<select ${a}>${options(f.options,value)}</select>`:f.type==='textarea'?`<textarea ${a}>${esc(value)}</textarea>`:`<input type="${['url','email','number','date'].includes(f.type)?f.type:'text'}" ${a} value="${esc(value)}">`}
function header(){return `${!shared?`<div class="pages-access"><div><strong>${tr('OmyCare · Support Blueprint','OmyCare · Support Blueprint')}</strong><span>${tr('Démonstration locale : les réponses restent dans ce navigateur. Pour travailler avec votre consultante, ouvrez votre projet partagé.','Local demo: answers stay in this browser. To work with your consultant, open your shared project.')}</span></div><a href="https://support-blueprint.omycare-8737.chatgpt.site" class="shared-entry">${tr('Ouvrir mon projet partagé','Open my shared project')} ↗</a></div>`:''}<div class="topbar"><div><strong>${esc(d('company').values.name||tr('Mon projet Zendesk','My Zendesk project'))}</strong><div class="status" id="savestatus" role="status">${esc(saveStatus())}</div></div><div class="tools">${shared?`<select id="project-select" aria-label="${tr('Projet','Project')}">${cloud.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===cloud.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button data-project="reload">↻ ${tr('Actualiser','Refresh')}</button>`:''}<button data-action="export">${w('export')} ↗</button><button data-action="import">${w('import')}</button><select id="language" aria-label="Language"><option value="fr" ${state.lang==='fr'?'selected':''}>FR · Français</option><option value="en" ${state.lang==='en'?'selected':''}>EN · English</option></select></div></div><div class="projectnav">${[['tracking',tr('Suivi du projet','Project tracking')],['questionnaire',tr('Document client','Client questionnaire')],['meetings',tr('Réunions','Meetings')],['training',tr('Formations','Training')]].filter(([v])=>v!=='training'||canManage()||state.tracking.trainingIncluded).map(([v,label])=>`<button data-page="${v}" class="${pageView===v?'primary':''}">${label}</button>`).join('')}${cloud.role==='consultant'?`<button class="preview-toggle" data-project="preview">${clientPreview?tr('Retour consultante','Back to consultant'):tr('Aperçu client','Client preview')}</button>`:''}</div>${cloud.error?`<div class="notice error">${esc(cloud.error)} <button data-action="json">${tr('Exporter mes modifications','Export my changes')}</button></div>`:''}`}

function render(){if(pageView!=='questionnaire'){renderTracking();return}document.documentElement.lang=state.lang;const s=section(),x=d(s.id),count=sections.filter(s=>d(s.id).reviewed).length;const groups=[tr('01 · LES FONDATIONS','01 · FOUNDATIONS'),tr('02 · L’ESPACE DE TRAVAIL','02 · WORKSPACE'),tr('03 · LE QUOTIDIEN','03 · DAILY OPERATIONS'),tr('04 · LA MISE EN SERVICE','04 · LAUNCH')];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="assets/omycare-logo.png" alt="OmyCare"><div class="brand-subtitle">Support Blueprint</div></div><div class="byline">${tr('VOTRE PROJET ZENDESK, PAS À PAS','YOUR ZENDESK PROJECT, STEP BY STEP')}</div><nav aria-label="${tr('Étapes','Steps')}">${sections.map((a,i)=>`${i===0||a.group!==sections[i-1].group?`<div class="navgroup">${groups[a.group]}</div>`:''}<button class="navbtn ${state.step===i?'active':''} ${d(a.id).reviewed?'completed':''}" data-step="${i}" ${state.step===i?'aria-current="step"':''}><span class="num">${d(a.id).reviewed?'✓':String(i+1).padStart(2,'0')}</span>${esc(t(a.title))}</button>`).join('')}</nav><div class="sidebarfoot">${tr('Un peu aujourd’hui. La suite quand vous voulez.','A little today. The rest when you’re ready.')}<br><br><button data-action="new">＋ ${w('new')}</button></div></aside><main>${header()}<div class="workspace"><div class="pageheading"><div><div class="eyebrow">${tr('ÉTAPE','STEP')} ${String(state.step+1).padStart(2,'0')} / ${sections.length}</div><h1>${esc(t(s.title))}</h1><p>${esc(t(s.desc))}</p></div><div><span class="duration">◷ ${s.time} min</span><div class="progressblock"><small>${count}/${sections.length} ${tr('étapes relues','steps reviewed')}</small><div class="progress"><i style="width:${count/sections.length*100}%"></i></div></div></div></div>${s.id==='review'?review():`<div class="layout"><div><section class="card"><div class="cardhead"><h2>${tr('À vous de jouer','Make it yours')}</h2><span class="stepbadge">${x.reviewed?w('reviewed'):w('draft').split(' · ')[0]}</span></div>${(s.fields||[]).length?`<div class="formgrid">${s.fields.map(f=>`<div class="field ${f.type==='textarea'?'wide':''}"><label for="f-${f.key}">${esc(t(f.label))}</label>${input(f,x.values[f.key]||'',`id="f-${f.key}" data-field="${f.key}"`)}</div>`).join('')}</div>`:''}<details class="example"><summary>${w('example')}</summary><p>${esc(t(s.example))}</p><button data-action="sample">＋ ${w('use')}</button></details>${s.cols?table(s,x):`<div id="validation" class="error" role="status">${issues(s).map(esc).join('<br>')}</div>`}<div class="hint">${esc(t(s.tip))}</div>${s.id==='company'?accessView():''}${extensionsView(s.id)}<label for="notes">${w('notes')}</label><textarea id="notes" placeholder="${tr('Une question ? Une décision à prendre ensemble ?','A question? A decision to make together?')}">${esc(x.notes)}</textarea><div class="actions" style="margin-top:16px"><label style="font-weight:400"><input id="deferred" type="checkbox" style="width:auto" ${x.deferred?'checked':''}> ${w('skip')}</label><button data-action="reviewed">${x.reviewed?'✓ ':''}${w('done')}</button></div></section></div><aside class="right"><section class="card"><div class="previewlabel"><strong>${w('preview')}</strong><span class="live">${w('live')}</span></div><div id="simulation">${preview(s)}</div><p class="muted" style="font-size:.75rem;margin:14px 0 0">${tr('Reconstitution pédagogique inspirée de Zendesk Support. Aucun ticket réel n’est modifié.','Educational recreation inspired by Zendesk Support. No real tickets are changed.')}</p></section><section class="card sources"><h3>${w('source')}</h3>${(s.refs||[]).map(k=>`<a target="_blank" rel="noopener" href="https://support.zendesk.com/hc/en-us/articles/${sources[k][0]}">${esc(sources[k][1])} ↗</a>`).join('')||`<p class="muted">${tr('Un atelier de cadrage à valider avec votre consultante.','A planning exercise to review with your consultant.')}</p>`}<small>${tr('Documentation officielle consultée le 22/09/2026. Fonctions à valider selon votre offre.','Official documentation checked on 22 Sep 2026. Features require plan verification.')}</small></section></aside></div>`}<div class="footnav"><button data-step="${state.step-1}" ${state.step===0?'disabled':''}>← ${w('back')}</button><button class="primary" data-step="${state.step+1}" ${state.step===sections.length-1?'disabled':''}>${w('next')} →</button></div></div></main></div><input type="file" id="importfile" accept="application/json,.json" hidden><div id="dialoghost"></div>`;bind();}
function table(s,x){return `<div class="tablehelp">${tr('Comme dans Excel : cliquez pour saisir, ou collez une plage de cellules. Options multiples : séparez par | ou par un saut de ligne.','Like Excel: click to edit or paste a range of cells. Multiple options: separate with | or a new line.')}</div><div class="tablewrap"><table><thead><tr>${s.cols.map(c=>`<th scope="col">${esc(t(c.label))}</th>`).join('')}<th></th></tr></thead><tbody>${x.rows.map((r,i)=>`<tr>${s.cols.map((c,j)=>`<td>${input(c,r[c.key]||'',`data-row="${i}" data-col="${j}"`)}</td>`).join('')}<td><button data-remove="${i}" aria-label="${tr('Supprimer la ligne','Delete row')} ${i+1}">×</button></td></tr>`).join('')}</tbody></table></div><button data-action="add">＋ ${w('add')}</button><div id="validation" class="error" role="status">${issues(s).map(esc).join('<br>')}</div>`}
function blank(s){return Object.fromEntries(s.cols.map(c=>[c.key,'']))}const opts=r=>(r?.options||'').split(/[\n|]+/).map(s=>s.trim()).filter(Boolean);
function tree(items,clickable=false){const root=new Map();for(const item of items){let n=root;item.split('::').forEach((p,i,a)=>{const key=p.trim()||'—';if(!n.has(key))n.set(key,{children:new Map(),value:null});const entry=n.get(key);if(i===a.length-1)entry.value=item;n=entry.children})}function draw(n){return [...n.entries()].map(([k,v])=>v.children.size?`<details open><summary>▱ ${esc(k)}</summary>${draw(v.children)}${v.value!==null?leaf(k,v.value):''}</details>`:leaf(k,v.value)).join('')}function leaf(k,v){return `<button type="button" class="leaf" ${clickable?`data-select-option="${esc(v)}"`: `data-view="${esc(v)}"`}>${esc(k)}</button>`}return `<div class="tree">${draw(root)}</div>`}
function mock(body,title='Support'){return `<div class="mock"><div class="mockbar"><strong>▰ ${title}</strong><span>${tr('Aperçu','Preview')}</span></div><div class="mockbody"><div class="rail"><span>⌂</span><span>▤</span><span>♧</span><span>⚙</span></div><div class="mockcontent">${body}</div></div></div>`}
function empty(){return `<p class="muted">${tr('Ajoutez une ligne ou utilisez l’exemple pour voir le résultat ici.','Add a row or use the example to see the result here.')}</p>`}
function rowPicker(rows,label,key){return `<label for="sim-row">${label}</label><select id="sim-row" data-sim="row">${rows.map((r,i)=>`<option value="${i}" ${Number(sim.row||0)===i?'selected':''}>${esc(r[key]||tr('Ligne','Row')+' '+(i+1))}</option>`).join('')}</select>`}
function fieldControl(f,value='',attr=''){if(f.type==='dropdown'||f.type==='multiselect')return `<select ${f.type==='multiselect'?'multiple':''} ${attr}><option value="">—</option>${opts(f).map(o=>`<option value="${esc(o)}" ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`;if(f.type==='checkbox')return `<input type="checkbox" ${attr} style="width:auto">`;if(f.type==='textarea')return `<textarea ${attr}></textarea>`;if(f.type==='lookup')return `<input ${attr} placeholder="${tr('Rechercher un enregistrement (démo)','Search a record (demo)')}">`;return `<input type="${f.type==='date'?'date':['integer','decimal'].includes(f.type)?'number':'text'}" ${f.type==='decimal'?'step="any"':''} ${attr}>`}
function preview(s){const x=d(s.id),rows=x.rows,r=rows[Math.min(Number(sim.row||0),Math.max(0,rows.length-1))]||{};let body='';switch(s.sim){case'company':body=`<span class="ticketpill">${tr('Votre espace','Your workspace')}</span><div class="tickettitle">${esc(x.values.name||tr('Votre entreprise','Your company'))}</div><p>${esc(x.values.activity||tr('Votre activité apparaîtra ici.','Your business activity will appear here.'))}</p><div class="bubble">${esc(x.values.goal||tr('Quel changement ferait une vraie différence ?','What change would make a real difference?'))}</div><div class="chips">${(x.values.languages||'FR, EN').split(',').map(l=>`<span class="chip">${esc(l)}</span>`).join('')}</div>`;break;
case'channels':body=rows.length?`${rowPicker(rows,tr('Point de contact','Contact point'),'address')}<div class="tickettitle">${esc(r.brand)}</div><label>${tr('Reçu via','Received via')}</label><div class="bubble">${esc(w(r.channel))} · ${esc(r.address)}</div><label>${tr('Groupe cible proposé','Proposed target group')}</label><div class="result">${esc(r.team||'—')}</div>`:empty();break;
case'teams':body=rows.length?`${rowPicker(rows,tr('Choisir une équipe','Choose a team'),'group')}<div class="tickettitle">${esc(r.group)}</div><p>${esc(r.mission)}</p><div class="bubble">${esc(r.members)}</div><div class="chips"><span class="chip">${esc(w(r.role))}</span></div><small>${esc(r.access)}</small>`:empty();break;
case'customers':body=rows.length?`${rowPicker(rows,tr('Organisation','Organization'),'organization')}<div class="tickettitle">${esc(r.organization)}</div><div class="chips"><span class="chip">${esc(r.segment)}</span></div><p>${esc(r.domains)}</p><div class="bubble">${esc(r.details)}</div><p>${esc(r.visibility)}</p>`:empty();break;
case'fields':body=rows.length?`${rowPicker(rows,tr('Champ à tester','Field to test'),'key')}<div class="tickettitle">#1042 · ${tr('Demande de livraison','Delivery request')}</div><label>${esc(r[state.lang]||r.key)} ${r.required&&r.required!=='optional'?'*':''}</label>${['dropdown','multiselect'].includes(r.type)?`${tree(opts(r),true)}<div class="result">${tr('Sélection','Selection')} : ${esc(sim.selected?.split('::').at(-1)||'—')}</div>`:fieldControl(r)}<div class="chips"><span class="chip">${esc(w(r.audience))}</span><span class="chip">${esc(w(r.required))}</span></div>${r.type==='multiselect'?`<small>${tr('Plusieurs feuilles peuvent être sélectionnées.','Multiple leaves can be selected.')}</small>`:''}`:empty();break;
case'forms':{if(!rows.length){body=empty();break}const fields=d('fields').rows;const definitions=rows.filter(a=>a.name===r.name);let allowed=(r.fields||'').split(',').map(v=>v.trim());body=rowPicker(rows,tr('Formulaire à tester','Form to test'),'name');const selected=sim.form||{};for(const f of fields.filter(f=>allowed.includes(f.key))){const cond=definitions.filter(a=>a.child===f.key&&a.parent);if(cond.length&&!cond.some(c=>selected[c.parent]===c.value))continue;if(r.audience==='customer'&&f.audience==='agent')continue;body+=`<label>${esc(f[state.lang]||f.key)}</label>${fieldControl(f,selected[f.key],`data-form-key="${esc(f.key)}" aria-label="${esc(f[state.lang]||f.key)}"`)}`}body+=`<div class="result">${tr('Changez le champ parent : les questions conditionnelles apparaissent.','Change the parent field: conditional questions appear.')}</div>`;break}
case'views':body=rows.length?`${tree(rows.map(r=>r.title).filter(Boolean))}<div class="result">${sim.view?esc(sim.view):tr('Cliquez sur une vue pour voir ses critères.','Click a view to see its criteria.')}</div>${sim.view?(()=>{const v=rows.find(r=>r.title===sim.view);return v?`<p>${tr('Tous les critères','All conditions')} :<br>${tr('Groupe','Group')} = ${esc(v.group||'—')}<br>${tr('Statut','Status')} = ${esc(w(v.status))}</p><small>${tr('Accès','Access')} : ${esc(v.access)}</small>`:''})():''}`:empty();break;
case'statuses':body=rows.length?`${rowPicker(rows,tr('Statut à tester','Status to test'),'label')}<span class="ticketpill">${esc(w(r.category))}</span><div class="tickettitle">${esc(r.label)}</div><p>${esc(r.meaning)}</p><div class="result">${tr('Prochaine action','Next action')} : ${esc(r.owner)}</div>`:empty();break;
case'macros':body=rows.length?`${rowPicker(rows,tr('Macro à appliquer','Macro to apply'),'title')}<label>${esc(w(r.visibility))}</label><div class="bubble" style="${r.visibility==='internal'?'background:#fff5d9':''}">${esc((r[state.lang]||'').replaceAll('{{ticket.requester.first_name}}','Camille'))}</div><div class="chips"><span class="chip">${esc(w(r.status))}</span><span class="chip">${esc(r.group)}</span></div><small>${tr('Camille est un prénom fictif. Les autres variables restent à valider.','Camille is a sample name. Other placeholders require validation.')}</small>`:empty();break;
case'rules':body=rows.length?`${rowPicker(rows,tr('Règle à tester','Rule to test'),'name')}<div class="simcontrols"><div><label>${tr('Groupe du ticket test','Test ticket group')}</label><input data-sim="group" value="${esc(sim.group??'Service client')}"></div><div><label>${tr('Statut du ticket test','Test ticket status')}</label><select data-sim="status">${options(['new','open','pending','hold','solved'],sim.status||'open')}</select></div>${r.kind==='automation'?`<label>${tr('Heures écoulées (démo)','Elapsed hours (demo)')}<input type="number" min="0" data-sim="hours" value="${esc(sim.hours||0)}"></label>`:''}</div><button data-action="testrule" style="margin-top:15px">▶ ${tr('Tester la règle','Test rule')}</button><div id="ruleresult" class="result">${tr('Test limité aux critères structurés ci-dessus.','Test limited to the structured criteria above.')}</div>`:empty();break;
case'sla':body=x.values.enabled==='no'?`<div class="result">${tr('Aucun SLA demandé. Définissez vos listes de travail dans les vues.','No SLA requested. Define work queues in Views.')}</div>`:rows.length?`${rowPicker(rows,tr('Priorité à tester','Priority to test'),'priority')}<h3 style="margin-top:20px">${esc(w(r.metric))}</h3><div class="metric">${esc(r.hours||'—')} h</div><small>${esc(w(r.clock))}</small><label>${tr('Durée comptabilisée (heures)','Counted time (hours)')}</label><input type="number" data-sim="elapsed" min="0" step="0.25" value="${esc(sim.elapsed||0)}"><div class="result">${slaResult(r)}</div><small>${tr('Comparaison simplifiée, sans calendrier ni transitions de statut.','Simplified comparison without schedules or status transitions.')}</small>`:empty();break;
case'knowledge':body=rows.length?`${rowPicker(rows,tr('Sujet à tester','Topic to test'),'topic')}<label>${tr('Client','Customer')}</label><div class="bubble">${esc(r.question)}</div><label>${tr('Réponse préparée','Prepared answer')}</label><div class="bubble">${esc(r.answer)}</div><div class="result">${tr('Passage à un agent','Agent handover')} : ${esc(r.handoff)}</div>`:empty();break;
case'launch':body=rows.length?`${rowPicker(rows,tr('Scénario de recette','Acceptance scenario'),'requirement')}<div class="tickettitle">${esc(r.requirement)}</div><div class="bubble">${esc(r.success)}</div><div class="chips"><span class="chip">${esc(w(r.state))}</span><span class="chip">${esc(r.owner)}</span></div>`:empty();break;
}return mock(body,s.sim==='forms'?tr('Centre d’aide','Help center'):'Support')}
function slaResult(r){const n=Number(r.hours),elapsed=Number(sim.elapsed||0);if(!r.hours||!Number.isFinite(n)||n<=0)return tr('Saisissez un objectif positif.','Enter a positive target.');return n-elapsed>=0?`${(n-elapsed).toFixed(2)} h ${tr('restantes','remaining')}`:`${tr('Objectif dépassé de','Target exceeded by')} ${(elapsed-n).toFixed(2)} h`}
function issues(s){const rows=d(s.id).rows,out=[];if(s.id==='company'){const v=d('company').values;if(v.account_owner_email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.account_owner_email))out.push(tr('Vérifiez l’email du propriétaire du compte.','Check the account owner’s email.'));if(v.zendesk_url){try{const u=new URL(v.zendesk_url);if(u.protocol!=='https:'||u.username||u.password||!u.hostname.endsWith('.zendesk.com'))throw Error()}catch{out.push(tr('Utilisez l’adresse HTTPS de votre instance, par exemple https://entreprise.zendesk.com.','Use your account HTTPS address, for example https://company.zendesk.com.'))}}}for(const r of rows)for(const c of s.cols||[])if(c.type==='select'&&r[c.key]&&!c.options.includes(r[c.key]))out.push(tr('Choix non reconnu : ','Unrecognized choice: ')+r[c.key]);if(s.id==='fields'){const keys=new Set();for(const r of rows){if(!/^[a-z][a-z0-9_]*$/.test(r.key||''))out.push(tr('Clé interne requise : lettres minuscules, chiffres, _.','Internal key required: lowercase letters, digits, _.'));if(keys.has(r.key))out.push(tr('Clé dupliquée : ','Duplicate key: ')+r.key);keys.add(r.key);if(['dropdown','multiselect'].includes(r.type)&&!opts(r).length)out.push(tr('Ajoutez les options du champ : ','Add options for field: ')+r.key);if(opts(r).some(o=>o.length>255||o.split('::').some(p=>!p.trim())))out.push(tr('Option trop longue ou niveau vide.','Option too long or empty hierarchy level.'));if(opts(r).length!==new Set(opts(r)).size)out.push(tr('Options dupliquées.','Duplicate options.'));if(!r.fr||!r.en||!r.type)out.push(tr('Renseignez les deux libellés et le type.','Enter both labels and a type.'));if(r.audience!=='customer_edit'&&r.required==='submit')out.push(tr('Un champ obligatoire à l’envoi doit être modifiable par le client.','A field required on submission must be customer-editable.'));}}
if(s.id==='views')for(const r of rows)if(!r.title||r.title.split('::').length>3||r.title.split('::').some(p=>!p.trim()))out.push(tr('Nom requis : dossier::sous-dossier::vue au maximum.','Name required: at most folder::subfolder::view.'));
if(s.id==='forms'){const keys=d('fields').rows.map(f=>f.key);for(const r of rows){for(const k of (r.fields||'').split(',').map(v=>v.trim()).filter(Boolean))if(!keys.includes(k))out.push(tr('Champ inconnu : ','Unknown field: ')+k);if(r.parent&&(!keys.includes(r.parent)||!keys.includes(r.child)))out.push(tr('Vérifiez les clés de la condition.','Check condition field keys.'));if(r.parent&&r.parent===r.child)out.push(tr('Un champ ne peut pas dépendre de lui-même.','A field cannot depend on itself.'));}}
if(s.id==='sla')for(const r of rows)if(!r.priority||!r.metric||!r.clock||!r.hours||!Number.isFinite(Number(r.hours))||Number(r.hours)<=0)out.push(tr('SLA : priorité, mesure, calendrier et durée positive requis.','SLA: priority, metric, clock and positive duration required.'));
return [...new Set(out)]}
function refreshPreview(){const p=$('#simulation');if(p){p.innerHTML=preview(section());bindPreview()}const v=$('#validation');if(v)v.innerHTML=issues(section()).map(esc).join('<br>')}
function bind(){bindProjectUI();bindExtensions();bindAccess();document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{state.step=Number(b.dataset.step);sim={};persist();render();window.scrollTo(0,0)});$('#language').onchange=e=>{state.lang=e.target.value;persist();render()};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{d(section().id).values[el.dataset.field]=el.value;changed();refreshPreview()});$('#notes')?.addEventListener('input',e=>{d(section().id).notes=e.target.value;changed()});$('#deferred')?.addEventListener('change',e=>{d(section().id).deferred=e.target.checked;changed()});document.querySelectorAll('[data-row]').forEach(el=>{el.oninput=()=>{const s=section();d(s.id).rows[Number(el.dataset.row)][s.cols[Number(el.dataset.col)].key]=el.value;changed();refreshPreview()};el.onpaste=e=>{const text=e.clipboardData.getData('text/plain');if(!text.includes('\t')&&!text.includes('\n'))return;e.preventDefault();pasteGrid(text,Number(el.dataset.row),Number(el.dataset.col))}});document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{d(section().id).rows.splice(Number(el.dataset.remove),1);changed();render()});$('#importfile').onchange=importFile;bindPreview()}
function changed(){d(section().id).reviewed=false;persist()}
function bindPreview(){document.querySelectorAll('[data-sim]').forEach(el=>el.onchange=()=>{sim[el.dataset.sim]=el.value;if(el.dataset.sim==='row'){sim.selected='';sim.selectedSet=[];sim.form={}}refreshPreview()});document.querySelectorAll('[data-form-key]').forEach(el=>el.onchange=()=>{sim.form??={};sim.form[el.dataset.formKey]=el.value;refreshPreview()});document.querySelectorAll('[data-select-option]').forEach(el=>el.onclick=()=>{const r=d('fields').rows[Number(sim.row||0)];if(r?.type==='multiselect'){sim.selectedSet??=[];const value=el.dataset.selectOption;sim.selectedSet=sim.selectedSet.includes(value)?sim.selectedSet.filter(v=>v!==value):[...sim.selectedSet,value];sim.selected=sim.selectedSet.map(v=>v.split('::').at(-1)).join(', ')}else sim.selected=el.dataset.selectOption;refreshPreview()});document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>{sim.view=el.dataset.view;refreshPreview()});document.querySelectorAll('[data-action="testrule"]').forEach(el=>el.onclick=()=>action('testrule'))}
function parseDelimited(text,sep='\t'){const result=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else if(!cell||quote)quote=!quote;else cell+=ch}else if(!quote&&(ch===sep||ch==='\n'||ch==='\r')){row.push(cell);cell='';if(ch!==sep){result.push(row);row=[];if(ch==='\r'&&text[i+1]==='\n')i++}}else cell+=ch}row.push(cell);if(row.some(Boolean))result.push(row);return result}
function pasteGrid(text,row,col){const s=section(),data=parseDelimited(text);if(data.length>500){toast(tr('Maximum 500 lignes par collage.','Maximum 500 rows per paste.'));return}for(let i=0;i<data.length;i++){d(s.id).rows[row+i]??=blank(s);data[i].forEach((v,j)=>{if(s.cols[col+j])d(s.id).rows[row+i][s.cols[col+j].key]=v})}changed();render();toast(tr('Cellules collées. Vérifiez les choix des listes.','Cells pasted. Check select-list values.'))}
function action(a){const s=section(),x=d(s.id);if(a==='add'){x.rows.push(blank(s));changed();render()}if(a==='sample'){if(s.cols)x.rows.push(...structuredClone(s.sample));else Object.assign(x.values,s.sample);changed();render()}if(a==='reviewed'){const errors=issues(s);if(errors.length){toast(tr('Corrigez les points signalés avant validation.','Resolve the highlighted issues before reviewing.'));return}x.reviewed=!x.reviewed;persist();render()}if(a==='import')$('#importfile').click();if(a==='export'){pageView='questionnaire';state.step=sections.length-1;persist();render()}if(a==='new'&&!canManage())return;if(a==='new'&&shared){createProjectDialog();return}if(a==='new')confirmDialog(tr('Créer un nouveau projet ? Exportez le projet actuel pour le conserver.','Create a new project? Export the current project to keep it.'),()=>{state=fresh();sim={};persist();render()});if(a==='json')download('support-blueprint.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json');if(a==='csv')exportCSV();if(a==='xlsx')exportXLSX();if(a==='api')exportAPI();if(a==='print')window.print();if(a==='testrule'){const r=x.rows[Number(sim.row||0)];const match=!!r?.target&&!!r.group&&r.group===(sim.group??'Service client')&&r.status===(sim.status||'open')&&(r.kind==='trigger'||r.kind==='automation'&&r.hours!==''&&Number(sim.hours||0)>=Number(r.hours));$('#ruleresult').textContent=match?tr('Correspondance → Groupe proposé : ','Match → Proposed group: ')+r.target:tr('Pas de correspondance (ou règle incomplète).','No match (or incomplete rule).')}}
function confirmDialog(msg,fn){$('#dialoghost').innerHTML=`<dialog><h2>${tr('Confirmer','Confirm')}</h2><p>${esc(msg)}</p><div class="actions"><button id="cancel">${tr('Annuler','Cancel')}</button><button class="primary" id="confirm">${tr('Continuer','Continue')}</button></div></dialog>`;const dialog=$('dialog');dialog.showModal();$('#cancel').onclick=()=>dialog.close();$('#confirm').onclick=()=>{dialog.close();fn()}}
async function importFile(e){const file=e.target.files[0];if(!file)return;if(file.size>5e6){toast(tr('Fichier trop volumineux (5 Mo maximum).','File too large (5 MB maximum).'));return}try{const next=validate(JSON.parse(await file.text()));confirmDialog(tr('Remplacer ce projet par le fichier importé ? Exportez d’abord vos modifications si nécessaire.','Replace this project with the imported file? Export current changes first if needed.'),()=>{if(shared&&cloud.role!=='consultant')next.tracking=state.tracking;state=next;sim={};persist();render();toast(tr('Projet restauré.','Project restored.'))})}catch{toast(tr('Fichier invalide. Importez un export JSON Support Blueprint version 1.','Invalid file. Import a Support Blueprint version 1 JSON export.'))}e.target.value=''}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function safeCSV(v){v=String(v??'');if(/^[\s]*[=+@-]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"'}
function exportCSV(){const rows=[['section','record','field','label_fr','label_en','value']];for(const s of sections){const x=d(s.id);for(const f of s.fields||[])rows.push([s.id,'company',f.key,f.label.fr,f.label.en,x.values[f.key]||'']);x.rows.forEach((r,i)=>{for(const c of s.cols||[])rows.push([s.id,String(i+1),c.key,c.label.fr,c.label.en,r[c.key]||''])});rows.push([s.id,'meta','notes','Notes','Notes',x.notes],[s.id,'meta','reviewed','Relu','Reviewed',x.reviewed],[s.id,'meta','deferred','À décider','To decide',x.deferred])}for(const sheet of [...trackingSheets(),...extensionSheets()])sheet.rows.forEach((r,i)=>r.forEach((v,j)=>rows.push([sheet.name,String(i+1),String(j+1),'','',v])));download('support-blueprint.csv','\uFEFF'+rows.map(row=>row.map(safeCSV).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function exportAPI(){const errors=issues(sections.find(s=>s.id==='fields'));if(errors.length){toast(tr('Corrigez les champs avant de préparer le JSON technique.','Fix ticket field issues before preparing technical JSON.'));return}const map={dropdown:'tagger',multiselect:'multiselect',text:'text',textarea:'textarea',integer:'integer',decimal:'decimal',checkbox:'checkbox',date:'date',regexp:'regexp',lookup:'lookup'};const requests=[];const unsupported=[];for(const r of d('fields').rows){if(['regexp','lookup'].includes(r.type)){unsupported.push({key:r.key,reason:'Additional configuration required; not generated'});continue}const f={type:map[r.type],title:r[state.lang]||r.fr,title_in_portal:r[state.lang]||r.fr,required:r.required==='solve',visible_in_portal:r.audience!=='agent',editable_in_portal:r.audience==='customer_edit',required_in_portal:r.required==='submit'};if(['dropdown','multiselect'].includes(r.type))f.custom_field_options=opts(r).map((name,i)=>({name,value:`bp_${r.key}_${i+1}`}));if(r.type==='checkbox')f.tag=`bp_${r.key}`;requests.push({method:'POST',path:'/api/v2/ticket_fields.json',internal_key:r.key,body:{ticket_field:f}})}download('zendesk-ticket-fields-draft.json',JSON.stringify({draft:true,notExecuted:true,warning:'Consultant review required. Check existing fields, tag collisions, plan, translations and target account. Do not run twice. Numeric option tags are draft identifiers and must be frozen before deployment.',unsupported,requests},null,2),'application/json')}
function review(){const errors=sections.flatMap(s=>issues(s).map(v=>`${t(s.title)} : ${v}`));return `<div class="notice">${tr('Parcours adapté aux 26 onglets du modèle French Workflow. Les exports créent des fichiers séparés ; aucune écriture automatique dans le modèle Google Sheets. Le statut en haut indique si vos réponses sont partagées ou uniquement locales. Exportez le JSON pour conserver une copie complète.','This journey maps the 26 tabs of the French Workflow template. Exports create separate files; the source Google Sheet is not automatically overwritten. The status above shows whether your answers are shared or local only. Export JSON to keep a complete backup.')}</div><div class="reviewgrid"><section class="card"><h2>${tr('Votre dossier de configuration','Your configuration brief')}</h2>${sections.filter(s=>s.id!=='review').map(s=>`<div class="reviewrow"><button data-step="${sections.indexOf(s)}">${esc(t(s.title))}</button><small>${d(s.id).reviewed?'✓ '+w('reviewed'):d(s.id).deferred?w('skip'):w('todo')}<br>${d(s.id).rows.length} ${tr('lignes','rows')}</small></div>`).join('')}</section><div><section class="card"><h2>${tr('Sauvegarder & transmettre','Save & hand over')}</h2><p class="muted">${tr('JSON conserve tout le projet. CSV s’ouvre dans Excel avec les libellés français et anglais. Le JSON technique prépare uniquement les champs de ticket compatibles.','JSON preserves the full project. CSV opens in Excel with French and English labels. Technical JSON drafts only supported ticket fields.')}</p><div class="actions"><button class="primary" data-action="json">↓ ${tr('Projet JSON','Project JSON')}</button><button data-action="xlsx">↓ Excel · XLSX</button><button data-action="csv">↓ CSV</button><button data-action="api">↓ ${tr('Champs · JSON technique','Fields · technical JSON')}</button></div><p class="muted" style="margin-top:16px">${tr('Aucun export n’applique de changement à Zendesk. La consultante vérifie les correspondances, les identifiants et les droits avant import.','No export applies changes to Zendesk. Your consultant checks mappings, IDs and permissions before import.')}</p></section><section class="card"><h2>${tr('Points à vérifier','Items to review')}</h2>${errors.length?errors.map(e=>`<p class="error">${esc(e)}</p>`).join(''):`<p>${tr('Aucune erreur structurelle détectée dans les champs, les formulaires, les vues et les SLA. Une revue fonctionnelle reste nécessaire.','No structural errors detected in fields, forms, views and SLAs. Functional review is still required.')}</p>`}${sections.filter(s=>d(s.id).notes||d(s.id).deferred).map(s=>`<h3>${esc(t(s.title))}</h3><p>${esc(d(s.id).notes||w('skip'))}</p>`).join('')}</section><section class="card"><h3>${tr('Périmètre de cette version','Scope of this version')}</h3><p class="muted">${tr('Parcours de cadrage Support. Les réglages spécifiques Talk, Messaging, Guide, Explore, IA, objets personnalisés, routage omnicanal, SSO et applications nécessitent des ateliers complémentaires selon votre abonnement.','Support planning journey. Detailed Talk, Messaging, Guide, Explore, AI, custom objects, omnichannel routing, SSO and app configuration require additional workshops depending on your subscription.')}</p><button data-action="reviewed">${w('done')}</button></section></div></div>`}
if(shared){$('#app').innerHTML='<main class="workspace"><p>Chargement du projet / Loading project…</p></main>';bootstrap()}else render();

function exportXLSX(){const sheets=[{name:'Read me',rows:[['Support Blueprint','Configuration draft / Projet de configuration'],['Version',1],['Exported',new Date().toISOString()],['Source template','French Workflow — 26 tabs mapped; source remains unchanged'],['Important','No live Zendesk changes. Local-only answers. JSON required to restore the project.']]}];for(const s of sections.filter(s=>s.id!=='review')){const x=d(s.id),rows=[];if(s.fields?.length){rows.push(['Field / Champ','Value / Valeur']);for(const f of s.fields)rows.push([f.label.fr+' / '+f.label.en,x.values[f.key]||'']);rows.push([])}if(s.cols){rows.push(s.cols.map(c=>c.label.fr+' / '+c.label.en));for(const r of x.rows)rows.push(s.cols.map(c=>r[c.key]||''))}rows.push([],['Notes',x.notes],['Reviewed / Relu',String(x.reviewed)],['To decide / À décider',String(x.deferred)]);sheets.push({name:s.id,rows})}sheets.push(...trackingSheets(),...extensionSheets());const url=URL.createObjectURL(workbook(sheets));const a=document.createElement('a');a.href=url;a.download='support-blueprint.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

function canManage(){return cloud.role==='consultant'&&!clientPreview}
function stateName(k){const names={todo:['À faire','To do'],in_progress:['En cours','In progress'],blocked:['En attente / bloqué','Waiting / blocked'],done:['Terminé','Done'],excluded:['Hors périmètre','Out of scope']};return tr(...(names[k]||names.todo))}
function trackingShell(content,title,desc){document.documentElement.lang=state.lang;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="assets/omycare-logo.png" alt="OmyCare"><div class="brand-subtitle">Support Blueprint</div></div><div class="byline">${tr('VOTRE PROJET ZENDESK, PAS À PAS','YOUR ZENDESK PROJECT, STEP BY STEP')}</div><div class="navgroup">${tr('VOTRE ESPACE PROJET','YOUR PROJECT WORKSPACE')}</div>${[['tracking',tr('Vue d’ensemble','Overview')],['questionnaire',tr('Document client','Client questionnaire')],['meetings',tr('8 réunions · 30 minutes','8 meetings · 30 minutes')],['training',tr('Formations incluses','Included training')]].filter(([v])=>v!=='training'||canManage()||state.tracking.trainingIncluded).map(([v,label])=>`<button class="navbtn ${pageView===v?'active':''}" data-page="${v}">${label}</button>`).join('')}<div class="sidebarfoot">${tr('Le questionnaire et la configuration avancent ensemble.','Questionnaire and configuration progress together.')}<br><br>${canManage()?`<button data-action="new">＋ ${w('new')}</button>`:''}</div></aside><main>${header()}<div class="workspace"><div class="pageheading"><div><div class="eyebrow">${tr('VOTRE PROJET','YOUR PROJECT')}</div><h1>${title}</h1><p>${desc}</p></div><span class="duration">${canManage()?tr('Espace consultante','Consultant workspace'):tr('Espace client','Client workspace')}</span></div>${!shared?`<div class="notice">${tr('Mode local : ce site statique ne synchronise pas les projets entre appareils. Utilisez la version hébergée avec le service partagé pour travailler à plusieurs.','Local mode: this static site does not sync projects between devices. Use the hosted version with the shared service to collaborate.')}</div>`:''}${clientPreview?`<div class="notice">${tr('Aperçu de présentation uniquement. Les vrais accès clients sont contrôlés séparément.','Presentation preview only. Actual client access is controlled separately.')}</div>`:''}${content}</div></main></div><input type="file" id="importfile" accept="application/json,.json" hidden><div id="dialoghost"></div>`;bindProjectUI();$('#language').onchange=e=>{state.lang=e.target.value;render()};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));$('#importfile').onchange=importFile;bindTracking()}
function renderTracking(){const m=metrics(state);const title=pageView==='meetings'?tr('Vos réunions de projet','Your project meetings'):pageView==='training'?tr('Vos formations','Your training'):tr('Chaque avancée, au même endroit','Every update, in one place');const desc=pageView==='meetings'?tr('Un maximum de 8 réunions de 30 minutes, soit 4 heures prévues.','Up to 8 meetings of 30 minutes: 4 hours included.'):pageView==='training'?tr('Les ressources prévues dans votre accompagnement.','The resources included in your engagement.'):tr('Suivez vos réponses, le travail de configuration et les prochaines étapes.','Follow your answers, configuration work and next steps.');trackingShell(pageView==='meetings'?meetingsView(m):pageView==='training'?trainingView():dashboardView(m),title,desc)}
function stat(value,label,detail){return `<div class="statcard"><div class="metric">${value}</div><strong>${label}</strong><small>${detail}</small></div>`}
function dashboardView(m){return `<div class="stats">${stat(`${m.documentsDone}/${m.documentsTotal}`,tr('Document client','Client questionnaire'),tr('Étapes marquées comme relues','Stages marked as reviewed'))}${stat(`${m.tasksDone}/${m.tasksTotal}`,tr('Configuration Zendesk','Zendesk configuration'),tr('Tâches terminées dans le périmètre','In-scope tasks completed'))}${stat(`${m.meetingsDone}/8`,tr('Réunions réalisées','Meetings held'),`${m.meetingMinutes} / 240 min`)}${stat(`${m.hours.toFixed(2)} h`,tr('Travail de configuration','Configuration work'),tr('Temps saisi, hors réunions · pas une facture','Logged time, excluding meetings · not an invoice'))}</div><section class="card"><h2>${tr('Point de situation','Project update')}</h2>${canManage()?`<textarea id="project-summary" placeholder="${tr('Ce qui a avancé, ce qui manque, la prochaine étape…','What progressed, what is missing, the next step…')}">${esc(state.tracking.summary)}</textarea><small>${tr('Ce commentaire est visible par le client.','This comment is visible to the client.')}</small>`:`<p>${esc(state.tracking.summary||tr('Votre consultante ajoutera ici le prochain point de situation.','Your consultant will add the next project update here.'))}</p>`}</section><div class="tracking-columns"><section class="card"><div class="cardhead"><h2>${tr('Votre document','Your questionnaire')}</h2><span class="stepbadge">${m.documentsDone}/${m.documentsTotal}</span></div>${sections.filter(s=>s.id!=='review').map((s,i)=>{const data=d(s.id),started=data.notes||data.rows.length||Object.values(data.values).some(Boolean);return `<button class="doc-status" data-document="${i}"><span>${esc(t(s.title))}</span><small>${data.reviewed?'✓ '+w('reviewed'):data.deferred?w('skip'):started?tr('En cours','In progress'):tr('À compléter','To complete')}</small></button>`}).join('')}</section><section class="card"><h2>${tr('Dernières modifications','Recent changes')}</h2>${cloud.events.length?cloud.events.slice(0,12).map(e=>`<div class="event"><strong>${esc(eventText(e))}</strong><small>${esc(new Date(e.at).toLocaleString(state.lang==='fr'?'fr-FR':'en-GB'))} · ${esc(e.actor)}</small></div>`).join(''):`<p class="muted">${shared?tr('L’historique se construit à chaque enregistrement du projet.','History is created each time the project is saved.'):tr('L’historique partagé est disponible sur la version hébergée.','Shared history is available in the hosted version.')}</p>`}${canManage()&&shared?`<hr><h3>${tr('Accès de votre client','Client access')}</h3><p class="muted">${tr('Ajoutez son email pour autoriser ce projet. Il faudra aussi lui ouvrir l’accès au site via Partager. Aucun email n’est envoyé ici.','Add their email to authorize this project. You must also grant access to the site through Share. No email is sent here.')}</p><div class="inlineform"><input id="client-email" type="email" placeholder="client@example.com" aria-label="Email"><button data-project="member-add">${tr('Autoriser','Authorize')}</button></div><div id="member-list">${cloud.members.map(a=>`<div class="reviewrow"><small>${esc(a.email)}</small><button data-member-remove="${esc(a.email)}">${tr('Retirer','Remove')}</button></div>`).join('')}</div>`:''}</section></div><section class="card"><div class="cardhead"><div><h2>${tr('Le travail dans votre instance Zendesk','Work in your Zendesk account')}</h2><p class="muted">${tr('Configuration, vérifications et tests : les tâches nécessaires à la mise en service. Les états sont renseignés par votre consultante.','Configuration, checks and tests: the work needed for launch. Your consultant maintains these statuses.')}</p></div></div><div class="tasklist">${taskDefinitions.map(def=>taskView(def)).join('')}</div></section>`}
function taskView(def){const v=state.tracking.tasks.find(x=>x.id===def.id);return `<details class="task"><summary><span class="tasktitle">${esc(def[state.lang])}<small>${def.id}</small></span><span class="taskstatus ${v.status}">${stateName(v.status)}</span></summary><div class="taskbody"><p>${esc(def[state.lang==='fr'?'descFR':'descEN'])}</p>${canManage()?`<div class="formgrid"><div><label>${tr('État','Status')}</label><select data-task="${def.id}" data-property="status">${taskStates.map(k=>`<option value="${k}" ${v.status===k?'selected':''}>${stateName(k)}</option>`).join('')}</select></div><div><label>${tr('Temps réellement passé (h)','Actual time spent (h)')}</label><input data-task="${def.id}" data-property="hours" type="number" min="0" max="10000" step="0.25" value="${v.hours}"></div><div class="field wide"><label>${tr('Commentaire visible par le client','Client-visible comment')}</label><textarea data-task="${def.id}" data-property="note">${esc(v.note)}</textarea></div></div>`:`<p>${esc(v.note||tr('Aucun commentaire pour le moment.','No comment yet.'))}</p><small>${v.hours} h · ${stateName(v.status)}</small>`}<button data-document="${sections.findIndex(s=>s.id===def.section)}">${tr('Voir la partie du document','View related questionnaire section')} →</button></div></details>`}
function meetingsView(m){return `<div class="stats three">${stat(`${m.meetingsDone}/8`,tr('Réunions réalisées','Meetings held'),tr('Seules les réunions cochées sont décomptées','Only checked meetings are counted'))}${stat(`${8-m.meetingsDone}`,tr('Réunions restantes','Meetings remaining'),`${(8-m.meetingsDone)*30} min`)}${stat('4 h',tr('Forfait maximum','Maximum allowance'),'8 × 30 min')}</div><div class="meetinggrid">${state.tracking.meetings.map(v=>`<section class="card meeting ${v.done?'held':''}"><div class="cardhead"><h2>${tr('Réunion','Meeting')} ${v.id}</h2><span class="stepbadge">30 min</span></div><label class="meeting-check"><input type="checkbox" data-meeting="${v.id}" data-property="done" ${v.done?'checked':''} ${!canManage()?'disabled':''}>${tr('Réunion réalisée','Meeting held')}</label><label>${tr('Date','Date')}</label><input type="date" data-meeting="${v.id}" data-property="date" value="${v.date}" ${!canManage()?'disabled':''}><label style="margin-top:15px">${tr('Sujet / compte rendu','Topic / notes')}</label>${canManage()?`<textarea data-meeting="${v.id}" data-property="note">${esc(v.note)}</textarea>`:`<p>${esc(v.note||'—')}</p>`}</section>`).join('')}</div>`}
function trainingView(){
 const trk=state.tracking,visible=cloud.resources.filter(r=>trk.trainingIncluded&&trk.trainingIds.includes(r.id));
 return `${canManage()?`<section class="card"><label class="meeting-check"><input id="training-included" type="checkbox" ${trk.trainingIncluded?'checked':''}>${tr('Les formations sont incluses dans ce projet','Training is included in this project')}</label><p class="muted">${tr('Activez uniquement les formations prévues dans la prestation.','Enable only the training included in this engagement.')}</p>${trk.trainingIncluded?cloud.resources.map(r=>`<label class="resource-choice"><input type="checkbox" data-resource="${esc(r.id)}" ${trk.trainingIds.includes(r.id)?'checked':''}>${esc(r[state.lang])}</label>`).join(''):''}</section>`:''}
 ${trk.trainingIncluded?`<div class="trainingcards">${visible.map(r=>{const url=unlockedCourses.get(`${cloud.id}:${r.id}`)||(!r.requiresCode?r.url:'');return `<section class="card traininglink"><span class="stepbadge">${tr('Inclus','Included')}</span><h2>${esc(r[state.lang])}</h2>${url?`<a class="button primary" href="${esc(safeTrainingURL(url))}" target="_blank" rel="noopener noreferrer">${tr('Ouvrir la formation','Open training')} ↗</a>`:shared?`<form data-unlock="${esc(r.id)}"><label for="code-${esc(r.id)}">${tr('Code fourni par OmyCare','Code provided by OmyCare')}</label><input id="code-${esc(r.id)}" type="password" autocomplete="off" maxlength="128" required><button class="primary">${tr('Accéder à la formation','Access training')}</button><p role="status"></p></form>`:`<p>${tr('La saisie du code est disponible dans le portail partagé.','Enter your code in the shared portal.')}</p><a href="https://support-blueprint.omycare-8737.chatgpt.site" target="_blank" rel="noopener">${tr('Ouvrir le portail','Open portal')} ↗</a>`}</section>`}).join('')||`<section class="card"><p>${tr('Votre consultante activera ici les formations prévues.','Your consultant will enable your training here.')}</p></section>`}</div>`:canManage()?`<div class="notice">${tr('Formations masquées pour ce projet.','Training is hidden for this project.')}</div>`:''}
 ${canManage()?`<section class="card"><h2>${tr('Catalogue commun des formations','Shared training catalog')}</h2><p class="muted">${tr('Ces liens sont réutilisés pour tous vos projets. Les deux formations OmyCare demandent leur code dans ce portail. Les pages GitHub de destination restent accessibles directement tant que leur hébergement est public.','These links are reused across projects. The two OmyCare courses require their code in this portal. The destination GitHub pages remain directly accessible while their hosting is public.')}</p><div id="catalog-rows">${cloud.resources.map((r,i)=>`<div class="catalogrow"><input data-catalog="${i}" data-property="fr" value="${esc(r.fr)}" aria-label="Titre français" placeholder="Titre français"><input data-catalog="${i}" data-property="en" value="${esc(r.en)}" aria-label="English title" placeholder="English title"><input data-catalog="${i}" data-property="url" type="url" value="${esc(r.url)}" aria-label="URL" placeholder="https://…">${r.requiresCode?`<span class="stepbadge">${tr('Code requis','Code required')}</span>`:`<button data-resource-remove="${i}" aria-label="${tr('Supprimer','Delete')}">×</button>`}</div>`).join('')}</div><div class="actions"><button data-project="catalog-add">＋ ${tr('Ajouter une formation','Add training')}</button><button data-project="catalog-save" class="primary">${tr('Enregistrer le catalogue','Save catalog')}</button></div><p id="catalog-status" role="status"></p></section>`:''}`;
}

function eventText(e){let changes=[];try{changes=typeof e.changes==='string'?JSON.parse(e.changes):e.changes}catch{}return changes.map(c=>{const [kind,id,status]=c.split(':');if(kind==='document')return `${tr('Document','Questionnaire')} · ${t(sections.find(s=>s.id===id)?.title)||id}`;if(kind==='task')return `${taskDefinitions.find(t=>t.id===id)?.[state.lang]||id} · ${stateName(status)}`;if(kind==='meeting')return `${tr('Réunion','Meeting')} ${id} · ${status==='done'?tr('réalisée','held'):tr('mise à jour','updated')}`;if(kind==='created')return tr('Projet créé','Project created');if(kind==='training')return tr('Accès aux formations mis à jour','Training access updated');if(kind==='access')return id==='received'?tr('Accès temporaire reçu','Temporary access received'):id==='retrieved'?tr('Accès temporaire récupéré','Temporary access retrieved'):tr('Accès temporaire supprimé','Temporary access removed');return tr('Point de situation mis à jour','Project update updated')}).join(' / ')}
function bindProjectUI(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{pageView=b.dataset.page;render()});document.querySelectorAll('[data-document]').forEach(b=>b.onclick=()=>{state.step=Number(b.dataset.document);pageView='questionnaire';render()});document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>projectAction(b.dataset.project));$('#project-select')?.addEventListener('change',async e=>{if(await flushCloud())await loadProject(e.target.value);else render()});document.querySelectorAll('[data-member-remove]').forEach(b=>b.onclick=async()=>{try{await api(`projects/${cloud.id}/members`,{method:'DELETE',body:JSON.stringify({email:b.dataset.memberRemove})});await loadMembers();render()}catch{toast(tr('Impossible de modifier les accès.','Could not update access.'))}})}
function bindTracking(){bindTrainingCodes();document.querySelectorAll('[data-task]').forEach(el=>el.onchange=()=>{if(!canManage())return;const r=state.tracking.tasks.find(t=>t.id===el.dataset.task);r[el.dataset.property]=el.dataset.property==='hours'?Math.max(0,Math.min(10000,Number(el.value)||0)):el.value;r.updatedAt=new Date().toISOString();persist();const openIds=[...document.querySelectorAll('.task[open] [data-task][data-property="status"]')].map(e=>e.dataset.task);render();openIds.forEach(id=>document.querySelector(`[data-task="${id}"]`)?.closest('details')?.setAttribute('open',''))});document.querySelectorAll('[data-meeting]').forEach(el=>el.onchange=()=>{if(!canManage())return;const r=state.tracking.meetings.find(m=>m.id===Number(el.dataset.meeting));r[el.dataset.property]=el.dataset.property==='done'?el.checked:el.value;if(r.done&&!r.date)r.date=new Date().toLocaleDateString('en-CA');persist();render()});$('#project-summary')?.addEventListener('input',e=>{state.tracking.summary=e.target.value;persist()});$('#training-included')?.addEventListener('change',e=>{state.tracking.trainingIncluded=e.target.checked;persist();render()});document.querySelectorAll('[data-resource]').forEach(el=>el.onchange=()=>{const id=el.dataset.resource;state.tracking.trainingIds=el.checked?[...new Set([...state.tracking.trainingIds,id])]:state.tracking.trainingIds.filter(v=>v!==id);persist();render()});document.querySelectorAll('[data-catalog]').forEach(el=>el.oninput=()=>{cloud.resources[Number(el.dataset.catalog)][el.dataset.property]=el.value});document.querySelectorAll('[data-resource-remove]').forEach(el=>el.onclick=()=>{cloud.resources.splice(Number(el.dataset.resourceRemove),1);render()})}
function trackingSheets(){const t=state.tracking;return [{name:'Implementation',rows:[['Jira','FR','EN','Status','Hours','Client note'],...taskDefinitions.map(d=>{const r=t.tasks.find(v=>v.id===d.id);return[d.id,d.fr,d.en,r.status,r.hours,r.note]})]},{name:'Meetings',rows:[['Meeting','Held','Date','Duration (minutes)','Notes'],...t.meetings.map(m=>[m.id,String(m.done),m.date,30,m.note])]},{name:'Training',rows:[['Included',String(t.trainingIncluded)],['FR','EN','URL'],...cloud.resources.filter(r=>t.trainingIncluded&&t.trainingIds.includes(r.id)).map(r=>[r.fr,r.en,r.url])]}]}
async function api(path,options={}){const r=await fetch('/api/blueprint/'+path,{...options,headers:{'Content-Type':'application/json'},credentials:'same-origin'});if(!r.ok){const e=new Error('request');e.status=r.status;try{e.code=(await r.json()).error}catch{}throw e}return r.json()}
async function bootstrap(){try{const session=await api('session');cloud.role=session.role;const list=await api('projects');cloud.projects=list.projects;cloud.ready=true;if(cloud.role==='consultant'){const c=await api('catalog');cloud.resources=c.resources;catalogRevision=c.revision}if(cloud.projects.length){await loadProject(cloud.projects[0].id)}else if(cloud.role==='consultant'){cloud.ready=true;render();createProjectDialog()}else $('#app').innerHTML=`<main class="workspace"><section class="card"><h1>${tr('Aucun projet attribué','No project assigned')}</h1><p>${tr('Votre consultante doit autoriser votre email pour votre projet.','Your consultant needs to authorize your email for your project.')}</p></section></main>`}catch(e){cloud.error=tr('Le projet partagé est indisponible. Réessayez sans effacer votre sauvegarde locale.','The shared project is unavailable. Retry without deleting your local backup.');$('#app').innerHTML=`<main class="workspace"><section class="card"><h1>${tr('Connexion au projet','Connecting to your project')}</h1><p>${esc(cloud.error)}</p><button id="retry-cloud">${tr('Réessayer','Retry')}</button></section></main>`;$('#retry-cloud').onclick=bootstrap}}
async function loadMembers(){if(cloud.role==='consultant'&&cloud.id)cloud.members=(await api(`projects/${cloud.id}/members`)).members}
async function loadProject(id){try{const p=await api('projects/'+id);const language=state.lang;state=validate(p.data);state.lang=language;cloud.id=id;unlockedCourses.clear();cloud.access=await api(`projects/${id}/credentials`);cloud.revision=p.revision;cloud.resources=p.trainingResources;if(cloud.role==='consultant'){const catalog=await api('catalog');cloud.resources=catalog.resources;catalogRevision=catalog.revision}cloud.events=p.events;cloud.dirty=false;cloud.error='';await loadMembers();render()}catch{toast(tr('Impossible de charger le projet.','Could not load the project.'))}}
async function flushCloud(){clearTimeout(saveTimer);if(!shared||!cloud.id)return true;if(cloud.error)return false;if(cloud.busy){await new Promise(r=>setTimeout(r,150));return flushCloud()}if(!cloud.dirty)return true;cloud.busy=true;cloud.dirty=false;setSaveStatus();const snapshot=structuredClone(state);try{const result=await api('projects/'+cloud.id,{method:'PUT',body:JSON.stringify({revision:cloud.revision,data:snapshot})});cloud.revision=result.revision;if(result.at)cloud.events.unshift({at:result.at,actor:cloud.role==='consultant'?'Stephanie':tr('Client','Client'),changes:result.changes});cloud.busy=false;setSaveStatus();if(cloud.dirty)return flushCloud();return true}catch(e){cloud.busy=false;cloud.dirty=true;cloud.error=e.status===409?tr('Une autre personne a modifié ce projet. Exportez vos modifications, puis actualisez pour récupérer la dernière version.','Someone else changed this project. Export your changes, then refresh to load the latest version.'):tr('Enregistrement impossible. Vos modifications restent ouvertes : exportez-les ou réessayez.','Could not save. Your changes remain open: export them or retry.');render();return false}}
function createProjectDialog(){if(!canManage())return;$('#dialoghost').innerHTML=`<dialog><h2>${tr('Nouveau projet partagé','New shared project')}</h2><label>${tr('Nom de l’entreprise','Company name')}</label><input id="new-project-name"><label class="meeting-check"><input id="migrate-draft" type="checkbox">${tr('Reprendre les réponses actuellement ouvertes','Use the currently open answers')}</label><div class="actions"><button id="cancel-project">${tr('Annuler','Cancel')}</button><button class="primary" id="create-project">${tr('Créer','Create')}</button></div><p id="create-error" role="status"></p></dialog>`;$('dialog').showModal();$('#cancel-project').onclick=()=>{$('dialog').close()};$('#create-project').onclick=async()=>{const name=$('#new-project-name').value.trim();if(!name)return;const data=$('#migrate-draft').checked?structuredClone(state):fresh();data.sections.company.values.name=name;$('#create-project').disabled=true;try{if(cloud.id&&!await flushCloud()){return}const result=await api('projects',{method:'POST',body:JSON.stringify({name,data})});$('dialog')?.close();cloud.projects=(await api('projects')).projects;await loadProject(result.id)}catch{$('#create-error').textContent=tr('Création impossible. Réessayez.','Could not create. Try again.');$('#create-project').disabled=false}}}
async function projectAction(action){if(action==='preview'){clientPreview=!clientPreview;if(!canManage()&&pageView==='training'&&!state.tracking.trainingIncluded)pageView='tracking';render();return}if(action==='reload'){if(cloud.dirty||cloud.error){confirmDialog(tr('Vos modifications non enregistrées seront remplacées. Exportez-les avant de continuer.','Unsaved changes will be replaced. Export them before continuing.'),()=>{cloud.error='';loadProject(cloud.id)})}else await loadProject(cloud.id);return}if(!canManage())return;if(action==='catalog-add'){cloud.resources.push({id:crypto.randomUUID(),fr:'',en:'',url:''});render()}if(action==='catalog-save'){if(cloud.resources.some(r=>!r.fr||!r.en||!safeTrainingURL(r.url))){toast(tr('Ajoutez les deux titres et un lien HTTPS valide.','Add both titles and a valid HTTPS link.'));return}try{if(shared){const c=await api('catalog',{method:'PUT',body:JSON.stringify({revision:catalogRevision,resources:cloud.resources})});catalogRevision=c.revision;cloud.resources=c.resources}else localStorage.setItem('blueprint-training-catalog',JSON.stringify(cloud.resources));toast(tr('Catalogue enregistré.','Catalog saved.'));render()}catch{toast(tr('Catalogue non enregistré. Actualisez avant de réessayer.','Catalog not saved. Refresh before retrying.'))}}if(action==='member-add'){const email=$('#client-email').value.trim();if(!email)return;try{await api(`projects/${cloud.id}/members`,{method:'POST',body:JSON.stringify({email})});await loadMembers();render();toast(tr('Accès au projet autorisé. Aucun email envoyé.','Project access authorized. No email sent.'))}catch{toast(tr('Vérifiez l’email et réessayez.','Check the email and try again.'))}}}
if(typeof window!=='undefined'){window.addEventListener?.('beforeunload',e=>{if(shared&&(cloud.dirty||cloud.busy)){e.preventDefault();e.returnValue=''}});if(!shared){try{cloud.resources=JSON.parse(localStorage.getItem('blueprint-training-catalog')||JSON.stringify(defaultCourses))}catch{}render()}}

if(shared&&typeof window!=='undefined')setInterval(async()=>{if(!cloud.id||cloud.dirty||cloud.busy||cloud.error||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;try{const p=await api('projects/'+cloud.id);if(p.revision!==cloud.revision||JSON.stringify(p.trainingResources)!==JSON.stringify(cloud.resources)){const step=state.step,lang=state.lang;state=validate(p.data);state.step=step;state.lang=lang;cloud.revision=p.revision;cloud.events=p.events;cloud.resources=p.trainingResources;render()}}catch{}},30000);
function extensionsView(id){return extensionDefinitions.filter(e=>e.section===id).map(e=>`<details class="extension-grid"><summary>${esc(t(e.title))} <small>· ${state.extensions[e.id].length} ${tr('lignes','rows')}</small></summary><p class="muted">${esc(t(e.help))}</p><p class="extension-example">${tr('Exemple','Example')} : ${esc(t(e.example))}</p><div class="tablewrap"><table><thead><tr>${e.cols.map(c=>`<th>${esc(t(c.label))}</th>`).join('')}<th></th></tr></thead><tbody>${state.extensions[e.id].map((r,i)=>`<tr>${e.cols.map((c,j)=>`<td><input data-ext="${e.id}" data-ext-row="${i}" data-ext-col="${j}" aria-label="${esc(t(c.label))}" value="${esc(r[c.key])}"></td>`).join('')}<td><button data-ext-remove="${e.id}:${i}" aria-label="${tr('Supprimer','Delete')}">×</button></td></tr>`).join('')}</tbody></table></div><button data-ext-add="${e.id}" ${e.max&&state.extensions[e.id].length>=e.max?'disabled':''}>＋ ${w('add')}</button><small> ${tr('Onglet source','Source tab')} : ${esc(e.sheet)}</small></details>`).join('')}
function bindExtensions(){const reopen=()=>{const open=[...document.querySelectorAll('.extension-grid[open] [data-ext-add]')].map(e=>e.dataset.extAdd);render();open.forEach(id=>document.querySelector(`[data-ext-add="${id}"]`)?.closest('details')?.setAttribute('open',''))};document.querySelectorAll('[data-ext-add]').forEach(el=>el.onclick=()=>{const def=extensionDefinitions.find(e=>e.id===el.dataset.extAdd);if(def.max&&state.extensions[def.id].length>=def.max)return;state.extensions[def.id].push(Object.fromEntries(def.cols.map(c=>[c.key,''])));changed();reopen()});document.querySelectorAll('[data-ext-remove]').forEach(el=>el.onclick=()=>{const[id,i]=el.dataset.extRemove.split(':');state.extensions[id].splice(Number(i),1);changed();reopen()});document.querySelectorAll('[data-ext]').forEach(el=>{el.oninput=()=>{const def=extensionDefinitions.find(e=>e.id===el.dataset.ext);state.extensions[def.id][Number(el.dataset.extRow)][def.cols[Number(el.dataset.extCol)].key]=el.value;changed()};el.onpaste=e=>{const raw=e.clipboardData.getData('text/plain');if(!raw.includes('\t'))return;e.preventDefault();const def=extensionDefinitions.find(x=>x.id===el.dataset.ext),rows=parseDelimited(raw).slice(0,500),start=Number(el.dataset.extRow),column=Number(el.dataset.extCol);rows.forEach((row,i)=>{if(def.max&&start+i>=def.max)return;state.extensions[def.id][start+i]??={};row.forEach((v,j)=>{if(def.cols[column+j])state.extensions[def.id][start+i][def.cols[column+j].key]=v})});changed();reopen()}})}
function extensionSheets(){return extensionDefinitions.map(e=>({name:e.sheet,rows:[e.cols.map(c=>t(c.label)),...state.extensions[e.id].map(r=>e.cols.map(c=>r[c.key]))]}))}

function accessView(){
 const pending=cloud.access?.pending;
 return `<div class="accessbox"><h3>${tr('Accès pour votre consultante','Access for your consultant')}</h3><p>${tr('Créez de préférence un compte nominatif pour','Preferably create a named account for')} <strong>stephanie@omycare.fr</strong>. ${tr('Indiquez ensuite « Invitation envoyée » dans le statut ci-dessus.','Then select “Invitation sent” in the status above.')}</p><p class="muted">${tr('Ne collez jamais de mot de passe dans les notes ou les tableaux. Pour un accès temporaire, utilisez le bouton dédié.','Never paste a password into notes or tables. For temporary access, use the dedicated button.')}</p>${shared&&cloud.id?`<p role="status">${pending?tr('Un accès temporaire attend votre consultante. Expiration : ','Temporary access is waiting for your consultant. Expires: ')+esc(new Date(cloud.access.expiresAt).toLocaleDateString(state.lang)):tr('Aucun accès temporaire en attente.','No temporary access pending.')}</p><div class="actions"><button data-access="send">${tr('Transmettre un accès temporaire','Send temporary access')}</button><button data-access="refresh">${tr('Actualiser le statut','Refresh status')}</button>${pending&&canManage()?`<button data-access="reveal" class="primary">${tr('Récupérer une seule fois','Retrieve once')}</button>`:''}${pending?`<button data-access="delete">${tr('Supprimer l’accès déposé','Delete submitted access')}</button>`:''}</div>`:`<p>${tr('La transmission chiffrée est disponible dans le portail partagé.','Encrypted handover is available in the shared portal.')} <a href="https://support-blueprint.omycare-8737.chatgpt.site" target="_blank" rel="noopener">${tr('Ouvrir le portail','Open portal')} ↗</a></p>`}</div>`;
}
function closeAccessDialog(){const host=$('#dialoghost');$('dialog')?.close();if(host)host.innerHTML=''}
function bindAccess(){document.querySelectorAll('[data-access]').forEach(el=>el.onclick=async()=>{
 const path=`projects/${cloud.id}/credentials`;
 try{
  if(el.dataset.access==='refresh'){cloud.access=await api(path);render();return}
  if(el.dataset.access==='delete'){confirmDialog(tr('Supprimer cet accès temporaire ?','Delete this temporary access?'),async()=>{try{await api(path,{method:'DELETE',body:'{}'});cloud.access={pending:false};render()}catch{toast(tr('Suppression impossible. Réessayez.','Could not delete. Try again.'))}});return}
  if(el.dataset.access==='send'){
   $('#dialoghost').innerHTML=`<dialog class="access-dialog"><form id="credential-form"><h2>${tr('Transmettre un accès temporaire','Send temporary access')}</h2><p>${tr('Chiffré, disponible pendant 7 jours et récupérable une seule fois par Stephanie. Le secret ne figure pas dans le document exporté. Un nouvel envoi remplace le précédent.','Encrypted, available for 7 days and retrievable once by Stephanie. The secret is excluded from exports. A new submission replaces the previous one.')}</p><label for="access-user">${tr('Utilisateur','Username')}</label><input id="access-user" autocomplete="off" maxlength="512" required><label for="access-password">${tr('Mot de passe temporaire','Temporary password')}</label><input id="access-password" type="password" autocomplete="new-password" maxlength="2048" required><div class="actions"><button type="button" id="access-close">${tr('Annuler','Cancel')}</button><button type="submit" class="primary">${tr('Transmettre','Send')}</button></div><p id="access-message" role="status"></p></form></dialog>`;
   $('dialog').showModal();$('dialog').addEventListener('close',()=>{$('#dialoghost').innerHTML=''});$('#access-close').onclick=closeAccessDialog;
   $('#credential-form').onsubmit=async e=>{e.preventDefault();const username=$('#access-user').value,password=$('#access-password').value;$('#access-password').value='';const submit=e.target.querySelector('[type="submit"]');submit.disabled=true;try{const result=await api(path,{method:'POST',body:JSON.stringify({username,password})});cloud.access={pending:true,expiresAt:result.expiresAt};d('company').values.access_status='ready';d('company').reviewed=false;persist();closeAccessDialog();render();toast(tr('Accès transmis.','Access submitted.'))}catch{const message=$('#access-message');if(message)message.textContent=tr('Envoi impossible. Ressaisissez le mot de passe pour réessayer.','Could not send. Enter the password again to retry.');submit.disabled=false}};
   return;
  }
  if(el.dataset.access==='reveal'&&canManage()){
   el.disabled=true;const secret=await api(path+'/reveal',{method:'POST',body:'{}'});cloud.access={pending:false};
   $('#dialoghost').innerHTML=`<dialog class="access-dialog"><h2>${tr('Accès temporaire','Temporary access')}</h2><p>${tr('Cet accès a été retiré du coffre. Copiez-le avant de fermer cette fenêtre.','This access has been removed from the vault. Copy it before closing this window.')}</p><label for="retrieved-user">${tr('Utilisateur','Username')}</label><input id="retrieved-user" readonly value="${esc(secret.username)}"><label for="retrieved-password">${tr('Mot de passe','Password')}</label><input id="retrieved-password" type="password" readonly value="${esc(secret.password)}"><button id="toggle-secret">${tr('Afficher / masquer','Show / hide')}</button><button id="access-close" class="primary">${tr('Effacer et fermer','Clear and close')}</button></dialog>`;
   secret.username='';secret.password='';$('dialog').showModal();$('dialog').addEventListener('close',()=>{$('#dialoghost').innerHTML='';render()});$('#access-close').onclick=closeAccessDialog;$('#toggle-secret').onclick=()=>{const f=$('#retrieved-password');f.type=f.type==='password'?'text':'password'};
  }
 }catch{toast(tr('Opération impossible. Actualisez le statut et réessayez.','Could not complete the operation. Refresh the status and retry.'));el.disabled=false}
})}
function bindTrainingCodes(){document.querySelectorAll('[data-unlock]').forEach(form=>form.onsubmit=async e=>{
 e.preventDefault();const input=form.querySelector('input'),button=form.querySelector('button'),status=form.querySelector('[role="status"]'),code=input.value;input.value='';button.disabled=true;
 try{if(!await flushCloud())throw Error('save');const result=await api(`projects/${cloud.id}/training/${form.dataset.unlock}/unlock`,{method:'POST',body:JSON.stringify({code})});unlockedCourses.set(`${cloud.id}:${form.dataset.unlock}`,safeTrainingURL(result.url));render()}
 catch(error){status.textContent=error.status===429?tr('Trop de tentatives. Réessayez dans 15 minutes.','Too many attempts. Try again in 15 minutes.'):error.code==='incorrect_code'?tr('Code incorrect.','Incorrect code.'):tr('Accès indisponible. Vérifiez que cette formation est incluse.','Access unavailable. Check that this training is included.');button.disabled=false}
})}
